  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "A closely related staurosporine glycoside, LCS1269, is predicted to have human bioavailability greater than 30%, supporting the high-F endpoint for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C65"],
      "claim": "Ondansetron, a carbazole-based oral drug, has an absolute oral bioavailability of about 60%, supporting high oral bioavailability for related heteroaromatic scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Vinorelbine, a complex natural product administered orally, has an absolute bioavailability of 43 ± 13%, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Encainide, which shares an N-methylbenzamide motif with the query, has a mean oral bioavailability of 41.9%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Ofloxacin has an absolute oral bioavailability greater than 0.95, demonstrating that related heteroaromatic drugs can be almost completely absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Rifapentine, a large complex natural product, has an absolute oral bioavailability of 70% after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Minocycline, a fused polycyclic oral drug, has an oral bioavailability of 90–100%, supporting high F for complex polycyclic molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "No direct absolute oral bioavailability value is available for the query, but the closest staurosporine analog and multiple structurally related oral drugs consistently show F >20%, supporting a high prediction at the F>=20% threshold.",
